package com.orderflow.notification.config;import java.util.concurrent.ThreadPoolExecutor;import org.springframework.context.annotation.*;import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;@Configuration public class AsyncConfiguration{@Bean("notificationExecutor")ThreadPoolTaskExecutor notificationExecutor(NotificationProperties p){var x=new ThreadPoolTaskExecutor();x.setCorePoolSize(p.async().corePoolSize());x.setMaxPoolSize(p.async().maxPoolSize());x.setQueueCapacity(p.async().queueCapacity());x.setThreadNamePrefix("notification-live-");x.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());x.setWaitForTasksToCompleteOnShutdown(true);x.setAwaitTerminationSeconds(10);x.setStrictEarlyShutdown(true);x.initialize();return x;}}
